package leo.modules.output.LPoutput

import leo.modules.output.LPoutput.lpDatastructures._

object LPSignature {

  abstract class lpAxioms extends lpTerm{
    def name: lpConstantTerm
    def ty: lpMlType
  }

  case object lpEm extends lpAxioms{
    //  Π x: Prop, Prf (x ∨ ¬ x)
    override def name: lpConstantTerm = lpConstantTerm("em")
    override def ty: lpMlType = lpMlDependType(Seq(lpTypedVar(lpConstantTerm("x"),lpOtype.lift2Meta)),lpOlUntypedBinaryConnectiveTerm(lpOr,lpOlConstantTerm("x"),lpOlUnaryConnectiveTerm(lpNot,lpOlConstantTerm("x"))).prf)
    override def pretty: String = lpDeclaration(lpEm.name,Seq.empty,lpEm.ty).pretty
  }

  abstract class lpTheorems extends lpTerm {
    def name: lpConstantTerm
    override def pretty: String = name.pretty
  }

  object lpTheorems {
    case object eqImp extends lpTheorems {
      override def name: lpConstantTerm = lpConstantTerm("=⇒")
    }
  }

  case object lpDne extends lpAxioms {
    // symbol dne x : π(¬ ¬ x) → π x
    // todo: add proof encoding
    override def name: lpConstantTerm = lpConstantTerm("¬¬ₑ")

    override def ty: lpMlType = lpMlDependType(Seq(lpTypedVar(lpConstantTerm("x"), lpOtype.lift2Meta)),lpMlFunctionType(Seq(lpOlUnaryConnectiveTerm(lpNot,lpOlUnaryConnectiveTerm(lpNot,lpOlConstantTerm("x"))).prf,lpOlConstantTerm("x").prf)))

    override def pretty: String = lpDeclaration(lpDne.name, Seq.empty, lpDne.ty).pretty
  }

  case object lpPropExt extends lpAxioms {
    override def name: lpConstantTerm = lpConstantTerm("propExt")

    // Π x: Els (↑ o), Π y: Els (↑ o), (Prf x → Prf y) → (Prf y → Prf x) → Prf (eq x y)
    override def ty: lpMlType = lpMlDependType(Seq(lpTypedVar(lpConstantTerm("x"), lpOtype.lift2Meta),lpTypedVar(lpConstantTerm("y"), lpOtype.lift2Meta)), lpMlFunctionType(Seq(lpMlFunctionType(Seq(lpOlConstantTerm("x").prf,lpOlConstantTerm("y").prf)),lpMlFunctionType(Seq(lpOlConstantTerm("y").prf,lpOlConstantTerm("x").prf)),lpOlTypedBinaryConnectiveTerm(lpEq,lpOtype,lpOlConstantTerm("x"),lpOlConstantTerm("y")).prf)))

    override def pretty: String = lpDeclaration(lpPropExt.name, Seq.empty, lpPropExt.ty).pretty
  }

  val cnfLib: String = "require open Stdlib.Set Stdlib.Prop Stdlib.Classic Stdlib.FOL Stdlib.HOL Stdlib.Eq Stdlib.Impred Stdlib.FunExt Stdlib.PropExt Stdlib.Nat Stdlib.Bool Stdlib.List Stdlib.Epsilon Leo-III-lambdapi-lib.EPrules Leo-III-lambdapi-lib.SimpTactic Leo-III-lambdapi-lib.MetaTheorems;\n\nsymbol conj : \uD835\uDD43 o → τ o;\nrule conj ($l1 ⸬ ($c ⸬ $l)) ↪ ($l1 ∧ conj ($c ⸬ $l))\nwith conj ($l1 ⸬ □) ↪ $l1 \nwith conj □ ↪ ⊤;\n\nassert l0 l1 l2 ⊢ π (conj (l0 ⸬ l1 ⸬ l2  ⸬ l1 ⸬ □)) ≡ π (l0 ∧ (l1 ∧ (l2  ∧ l1)));\n\nopaque symbol conj_head (l0 : τ o) (l : \uD835\uDD43 o) : \n     π (conj (l0 ⸬ l)) → π (l0) ≔\nbegin\n    assume l0;\n    induction\n        {assume h1;\n        refine h1}   \n        {assume x0 l1 h1 h2;\n        refine ∧ₑ₁ h2}\nend; \n\nopaque symbol conj_correct (l0 : τ o) (l : \uD835\uDD43 o) : \n    π (conj (l0 ⸬ l)) → π (l0 ∧ conj l) ≔\nbegin\n    assume l0;\n    induction\n        {assume h1;\n        refine ∧ᵢ h1 ⊤ᵢ}\n        {assume x1 l1 h1 h2;\n        refine h2}\nend;\n\nopaque symbol conj_tail (l0 : τ o) (l : \uD835\uDD43 o) : \n     π (conj (l0 ⸬ l)) → π (conj l) ≔\nbegin\n    assume l0;\n    induction\n        {assume h1;\n        refine ⊤ᵢ}   \n        {assume x0 l1 h1 h2; \n        refine ∧ₑ₂ h2}\nend; \n\nopaque symbol indexes_shift (l: \uD835\uDD43 nat) (n : τ nat):\n    π (istrue (∈ eqn (n +1) (map (+1) l)) ⇒ istrue (∈ eqn n l))≔\nbegin\n    induction\n        {assume n x; refine x}\n        {assume n0;\n        induction\n            {assume h0 n h1; refine h1}\n            {assume n1 l h0 h1 n2 h2;\n            refine orₑ [eqn n2 n0] [eqn n2 n1 or ∈ eqn (n2 +1) (map (+1) l)] (eqn n2 n0 or (eqn n2 n1 or ∈ eqn n2 l)) h2 _ _\n                {assume h3;\n                refine orᵢ₁ (eqn n2 n1 or ∈ eqn n2 l) h3}\n                {assume h3;\n                refine orᵢ₂ (eqn n2 n0) (h1 n2 h3)}}}\nend;\n\n\n\nopaque symbol indexes_decrement (id : τ nat) (l0: τ o) (l: \uD835\uDD43 o): \n     π ((id +1) ∈ₙ (indexes (l0 ⸬ l))) → π (id ∈ₙ (indexes l))≔\nbegin\n    assume id l0 l;\n    assume h0; \n    have H1 : π ((istrue (∈ eqn (id +1) (iota 1 (size l)))) ⇒ (istrue (∈ eqn id (iota 0 (size l)))))\n        {have H2: π (iota 1 (size l) = map (+1) (iota 0 (size l)))\n            {refine (eq_sym (mapS_iota (size l) 0))};\n        rewrite H2;\n        refine indexes_shift (iota 0 (size l)) id};\n    refine H1 h0\nend;\n\n\nopaque symbol select (id : τ nat) (cnf: \uD835\uDD43 o) : \n    π (id ∈ₙ (indexes cnf)) → π (conj cnf) → π (literal cnf id) ≔\nbegin\n    induction \n        {induction\n            {assume h0 h1; refine h0}\n            {assume x cnf h0 h1 h2; \n            refine conj_head x cnf h2}}\n        {assume id h0;\n        induction\n            {assume b; refine ⊥ₑ b}\n            {assume x cnf h1 h2 h3;\n            have ConjImpCl : π (conj cnf ⇒ literal cnf id)\n                {refine h0 cnf (indexes_decrement id x cnf h2)};\n            refine literal_ext cnf x id (ConjImpCl (conj_tail x cnf h3))}}\nend;\n\n\n/******************************************************************************\n *  Lemmas\n ******************************************************************************/\n\nopaque symbol =⇒ [a b] : π (a = b) → π a → π b ≔\nbegin\n\tassume a b h0 h1;\n\trefine ind_eq (eq_sym h0) (λ x, x) h1\nend;\n\n/******************************************************************************\n *  De Morgan's Laws on ∧ and ∨\n ******************************************************************************/\n\nopaque symbol deMorgan_∧ x y : //lemma0\n π (¬(x ∧ y) = (¬ x ∨ ¬ y))≔\nbegin\n assume x y;\n refine propExt (¬(x ∧ y)) (¬ x ∨ ¬ y) _ _\n {assume h;\n     refine ∨ₑ (em x) _ _\n     {assume hx; refine ∨ᵢ₂ (λ hy, h (∧ᵢ hx hy))}\n     {assume hx; refine ∨ᵢ₁ hx}}\n {assume h hxy; \n     refine ∨ₑ h _ _\n     {assume hnx; refine hnx (∧ₑ₁ hxy)}\n     {assume hny; refine hny (∧ₑ₂ hxy)}}\nend;\n\nopaque symbol deMorgan_∨ x y : // lemma1 \n π (¬(x ∨ y) = (¬ x ∧ ¬ y))≔\nbegin\n assume x y;\n refine propExt (¬(x ∨ y)) (¬ x ∧ ¬ y) _ _\n {assume h; refine ∧ᵢ _ _ \n     {assume hx; refine h (∨ᵢ₁ hx)} \n     {assume hy; refine h (∨ᵢ₂ hy)}}\n {assume h hxy;\n     refine ∨ₑ hxy _ _\n     {assume hx; refine (∧ₑ₁ h) hx}\n     {assume hy; refine (∧ₑ₂ h) hy}}\nend;\n\n/******************************************************************************\n*  Implication Equivalences\n******************************************************************************/\n\nopaque symbol ⇒=∨ x y :  // lemma2\n π ((x ⇒ y) = (¬ x ∨ y))≔\nbegin\n assume x y;\n refine propExt (x ⇒ y) (¬ x ∨ y) _ _\n {assume h;\n     refine ∨ₑ (em x) _ _\n     {assume hx; refine ∨ᵢ₂ (h hx)}\n     {assume hnx; refine ∨ᵢ₁ hnx}}\n {assume h hx;\n     refine ∨ₑ h _ _\n     {assume hnx; refine ⊥ₑ (hnx hx)}\n     {assume hy; refine hy}}\nend;\n\nopaque symbol ¬⇒=∧¬ x y : // lemma3\n π (¬(x ⇒ y) = (x ∧ ¬ y))≔\nbegin\n assume x y;\n refine propExt (¬(x ⇒ y)) (x ∧ ¬ y) _ _\n {assume h;\n     refine ∧ᵢ _ _\n     {refine ∨ₑ (em x) _ _\n         {assume hx; refine hx}\n         {assume hnx; refine ⊥ₑ (h (λ z, ⊥ₑ (hnx z)))}}\n     {assume hy; refine h (λ _, hy)}}\n {assume h himp;\n     refine (∧ₑ₂ h) (himp (∧ₑ₁ h))}\nend;\n\n/******************************************************************************\n*  Distributivity\n******************************************************************************/\n\n// ... to mimic splitting in leo-III\n\nopaque symbol ∧∨_dist_l x y z : // lemma4\n π (((x ∧ y) ∨ z) = ((x ∨ z) ∧ (y ∨ z)))≔\nbegin\n assume x y z;\n refine propExt ((x ∧ y) ∨ z) ((x ∨ z) ∧ (y ∨ z)) _ _\n {assume h;\n     refine ∧ᵢ _ _\n     {refine ∨ₑ h _ _\n         {assume hxy; refine ∨ᵢ₁ (∧ₑ₁ hxy)}\n         {assume hz; refine ∨ᵢ₂ hz}}\n     {refine ∨ₑ h _ _\n         {assume hxy; refine ∨ᵢ₁ (∧ₑ₂ hxy)}\n         {assume hz; refine ∨ᵢ₂ hz}}}\n {assume h;\n     refine ∨ₑ (em z) _ _\n     {assume hz; refine ∨ᵢ₂ hz}\n     {assume hnz;\n         have hx : π x \n             {refine ∨ₑ (∧ₑ₁ h) _ _\n                 {assume hx; refine hx}\n                 {assume hz; refine ⊥ₑ (hnz hz)}};\n         have hy : π y \n             {refine ∨ₑ (∧ₑ₂ h) _ _\n                 {assume hy; refine hy}\n                 {assume hz; refine ⊥ₑ (hnz hz)}};\n         refine ∨ᵢ₁ (∧ᵢ hx hy)}}\nend;\n\nopaque symbol ∧∨_dist_r x y z : //lemma5\n π ((z ∨ (x ∧ y)) = ((z ∨ x) ∧ (z ∨ y)))≔\n begin\n     assume x y z;\n     rewrite ∨_com;\n     rewrite ∧∨_dist_l;\n     rewrite ∨_com z x;\n     rewrite ∨_com z y;\n     reflexivity\n end;\n\n/******************************************************************************\n*  Associativity of ∧\n******************************************************************************/\n\nopaque symbol ∧_assoc x y z : // \n π (((x ∧ y) ∧ z) = (x ∧ (y ∧ z)))≔\nbegin\n assume x y z;\n refine propExt ((x ∧ y) ∧ z) (x ∧ (y ∧ z)) _ _\n {assume h;\n refine ∧ᵢ (∧ₑ₁ (∧ₑ₁ h)) (∧ᵢ (∧ₑ₂ (∧ₑ₁ h)) (∧ₑ₂ h))}\n {assume h;\n refine ∧ᵢ (∧ᵢ (∧ₑ₁ h) (∧ₑ₁ (∧ₑ₂ h))) (∧ₑ₂ (∧ₑ₂ h))}\nend;\n\nopaque symbol ∨_assoc x y z : // \n π (((x ∨ y) ∨ z) = (x ∨ (y ∨ z)))≔\nbegin\n assume x y z;\n refine propExt ((x ∨ y) ∨ z) (x ∨ (y ∨ z)) _ _\n {assume h0;\n refine ∨ₑ h0 _ _\n    {assume h1; refine ∨ₑ h1 _ _\n        {assume h2; refine ∨ᵢ₁ h2}\n        {assume h2; refine ∨ᵢ₂ (∨ᵢ₁ h2)}}\n    {assume h1; refine ∨ᵢ₂ (∨ᵢ₂ h1)}}\n {assume h0; refine ∨ₑ h0 _ _\n    {assume h1; refine ∨ᵢ₁ (∨ᵢ₁ h1)}\n    {assume h1; refine ∨ₑ h1 _ _\n        {assume h2; refine ∨ᵢ₁ (∨ᵢ₂ h2)}\n        {assume h2; refine ∨ᵢ₂ h2}}}\nend;\n\n/******************************************************************************\n *  Classical Quantifier De Morgan\n ******************************************************************************/\n\n opaque symbol ¬∀=∃¬ (t : Set) (p : τ (t ⤳ o)) : //lemma6\n π (¬(∀ p) = (`∃ (x : τ t), ¬ (p x)))≔\nbegin\n assume t p;\n refine propExt (¬ (∀ p)) (`∃ x, ¬ (p x)) _ _\n {assume h;\n     refine ∨ₑ (em (`∃ x, ¬ p x)) _ _\n     {assume he; refine he}\n     {assume hne;\n         have forall_p : Π x : τ t, π (p x)\n             {assume a; refine ¬¬ₑ (p a) (λ hp, hne (∃ᵢ [t] [λ y, ¬ p y] a hp))};\n         refine ⊥ₑ (h (λ a, forall_p a))}}\n {assume h h2;\n     refine ∃ₑ [t] [λ y, ¬ p y] h (λ a hna, hna (h2 a))}\nend;\n\nopaque symbol ¬∃=∀¬ (t : Set) (p : τ (t ⤳ o)) : // lemma7\n π (¬(∃ p) = (`∀ (x : τ t), ¬ p x))≔     \nbegin\n assume t p;\n refine propExt (¬ (∃ p)) (`∀ x, ¬ p x) _ _\n {assume h a ha; refine h (∃ᵢ [t] [p] a ha)}\n {assume h1 h2; refine ∃ₑ [t] [p] h2 (λ a ha, (h1 a) ha)}\nend;\n\n/******************************************************************************\n*  Skolemisazion\n******************************************************************************/\n\nopaque symbol εᵢ_rev :  Π [a: Set], Π p: (τ a → Prop),  π (p (ε p)) → π (∃ p)≔\nbegin\n assume a p h;\n refine ∃ᵢ [a] [p] (ε p) h\nend;\n\nopaque symbol ∃_skolem (a: Set) (p: τ a → Prop) :  \n π ((∃ p) = (p (ε p)))≔\nbegin\n assume a p;\n refine propExt (∃ p) (p (ε p)) (εᵢ [a] p) (εᵢ_rev [a] p)\nend;\n\nopaque symbol ∀_skolem (a: Set) (p: τ a → Prop) :  \n π (¬ (∀ p) = ¬ (p (ε (λ x, ¬ (p x)))))≔\nbegin\n assume a p;\n rewrite ¬∀=∃¬;\n refine  propExt (`∃ x, ¬ (p x)) (¬ (p (ε (λ x, ¬ (p x))))) _ _\n     {assume h; refine ind_eq (eq_sym (∃_skolem a (λ x, ¬ (p x)))) (λ x, x) h}\n     {assume h; refine ind_eq (∃_skolem a (λ x, ¬ (p x))) (λ x, x) h}\nend;\n\n\n/******************************************************************************\n *  Quantifier Distributivity\n ******************************************************************************/\n\n opaque symbol ∀∧_dist_r t a (p : τ(t ⤳ o)): π ((a ∧ ∀ p) = (`∀ x, a ∧ p x))≔\n begin\n     assume t a p;\n     refine propExt (a ∧ ∀ p) (∀(λ x, a ∧ p x)) _ _\n         {assume h x;\n         refine ∧ᵢ (∧ₑ₁ h) ((∧ₑ₂ h) x)}\n         {assume h;\n         refine ∨ₑ (em (∀ p)) _ _\n             {assume h1;\n             refine ∧ᵢ (∧ₑ₁ (h (el t))) h1}\n             {assume h1;\n             have H0: π (¬ (p (ε (λ x, ¬ (p x)))))\n                 {refine =⇒ (∀_skolem t p) h1};\n             have H1: π (p (ε (λ x, ¬ (p x))))\n                 {refine ∧ₑ₂ (h (ε (λ x, ¬ (p x))))};\n             refine ⊥ₑ (H0 H1)}}\n end;\n \n opaque symbol ∀∧_dist_l t a (p : τ(t ⤳ o)): π ((∀ p ∧ a) = (`∀ x,p x ∧ a))≔\n begin\n     assume t a p;\n     refine propExt (∀ p ∧ a) (`∀ x, p x ∧ a) _ _\n         {assume h0 x;\n         rewrite ∧_com;\n         refine (=⇒ ((∀∧_dist_r t a p)) (=⇒ (∧_com (∀ p) a) h0)) x\n         }\n         {assume h0;\n         rewrite ∧_com;\n         have H0: π (`∀ x, a ∧ p x)\n             {assume x;\n             rewrite ∧_com;\n             refine h0 x};\n         refine =⇒ (eq_sym (∀∧_dist_r t a p)) H0\n         };\n end;\n \n opaque symbol ∀∨_dist_r t a (p : τ(t ⤳ o)): π ((a ∨ ∀ p) = (`∀ x, a ∨ p x))≔\n begin\n     assume t a p;\n     refine propExt (a ∨ ∀ p) (∀(λ x, a ∨ p x)) _ _\n         {assume h x;\n         refine ∨ₑ h _ _\n             {assume h0;\n             refine ∨ᵢ₁ h0}\n             {assume h0;\n             refine ∨ᵢ₂ (h0 x)}}\n         {assume h;\n         refine ∨ₑ (em (∀ p)) _ _\n             {assume h1;\n             refine ∨ᵢ₂ h1}\n             {assume h1;\n             have H0: π (¬ (p (ε (λ x, ¬ (p x)))))\n                 {refine =⇒ (∀_skolem t p) h1};\n             refine ∨ₑ (h (ε (λ x, ¬ (p x)))) _ _\n                 {assume h0;\n                 refine ∨ᵢ₁ h0}\n                 {assume h0;\n                 refine ⊥ₑ (H0 h0)}}}\n end;\n \n opaque symbol ∀∨_dist_l t a (p : τ(t ⤳ o)): π ((∀ p ∨ a) = (`∀ x,p x ∨ a))≔\n begin\n     assume t a p;\n     refine propExt (∀ p ∨ a) (`∀ x,p x ∨ a) _ _\n         {assume h0 x;\n         rewrite ∨_com;\n         refine (=⇒ ((∀∨_dist_r t a p)) (=⇒ (∨_com (∀ p) a) h0)) x}\n         {assume h0;\n         rewrite ∨_com;\n         have H0: π (`∀ x, a ∨ p x)\n             {assume x;\n             rewrite ∨_com;\n             refine h0 x};\n         refine =⇒ (eq_sym (∀∨_dist_r t a p)) H0};\n end;\n \n opaque symbol ∀_ext [t: Set] p q : π(`∀ (x : τ t), p x = q x) → π ((`∀ (x: τ t), p x) = (`∀ (x: τ t), q x))≔\n begin\n     assume t p q h;\n     refine propExt (`∀ (x: τ t), p x) (`∀ (x: τ t), q x) _ _\n         {assume h1 x;\n         refine =⇒ (h x) (h1 x)}\n         {assume h1 x;\n         refine =⇒ (eq_sym (h x)) (h1 x)}\n end;\n\n\n/******************************************************************************\n *  Defined Tactics\n ******************************************************************************/\n\n symbol normAsso ≔ #repeat ((#rewrite ∧_assoc) #orelse (#rewrite ∨_assoc));\n\n symbol allCNFids_list ≔ ((#rewrite deMorgan_∧) ⸬ (#rewrite deMorgan_∨) ⸬ (#rewrite ⇒=∨) ⸬ (#rewrite ¬⇒=∧¬) ⸬ (#and (#rewrite ∧∨_dist_l) normAsso) ⸬ (#and (#rewrite ∧∨_dist_r) normAsso) ⸬ (#rewrite ¬¬ₑ_eq) ⸬ □);\n \n symbol allCNFids_app ≔ #and (#and (#repeat (applyAny allCNFids_list)) normAsso) #reflexivity;"

}
